package net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.DcrInitialAccessToken;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueobject.AllowedGrantTypesVO;

class AllowedGrantTypesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of allowed grant types of dcr initial access token")
  void test_allowed_grant_types_value_holder_assign_plain_value() {
    Object holder = new Object();
    AllowedGrantTypesValueHolder<Object> value = new AllowedGrantTypesValueHolder<>(holder);
    Assertions.assertSame(holder, value.allowedGrantTypes("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAllowedGrantTypesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getAllowedGrantTypes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.allowedGrantTypesNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getAllowedGrantTypesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getAllowedGrantTypes().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of allowed grant types of dcr initial access token")
  void test_allowed_grant_types_value_holder_assign_value_object() {
    Object holder = new Object();
    AllowedGrantTypesValueHolder<Object> value = new AllowedGrantTypesValueHolder<>(holder);
    AllowedGrantTypesVO vo = AllowedGrantTypesVO.from("one");
    Assertions.assertFalse(value.getAllowedGrantTypesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.allowedGrantTypes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAllowedGrantTypesValue().orElseThrow());
    Assertions.assertSame(holder, value.allowedGrantTypes(Optional.empty()));
    Assertions.assertFalse(value.getAllowedGrantTypesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.allowedGrantTypes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAllowedGrantTypesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of allowed grant types of dcr initial access token against the original")
  void test_allowed_grant_types_value_holder_read() {
    Object holder = new Object();
    AllowedGrantTypesValueHolder<Object> value = new AllowedGrantTypesValueHolder<>(holder);
    AllowedGrantTypesVO vo = AllowedGrantTypesVO.from("one");
    AllowedGrantTypesVO other = AllowedGrantTypesVO.from("one");
    DcrInitialAccessToken original = Mockito.mock(DcrInitialAccessToken.class);
    Mockito.when(original.getAllowedGrantTypesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAllowedGrantTypes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAllowedGrantTypes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.allowedGrantTypes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAllowedGrantTypes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAllowedGrantTypes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of allowed grant types of dcr initial access token")
  void test_allowed_grant_types_value_holder_unset() {
    Object holder = new Object();
    AllowedGrantTypesValueHolder<Object> value = new AllowedGrantTypesValueHolder<>(holder);
    AllowedGrantTypesVO vo = AllowedGrantTypesVO.from("one");
    value.allowedGrantTypes(vo);
    Assertions.assertSame(holder, value.unsetAllowedGrantTypesIfMatches("allowedGrantTypes_other"));
    Assertions.assertTrue(value.getAllowedGrantTypesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAllowedGrantTypesIfMatches("allowedGrantTypes"));
    Assertions.assertFalse(value.getAllowedGrantTypesValue().isPresent(),
        "The field name must clear the value");
    value.allowedGrantTypes(vo);
    Assertions.assertSame(holder, value.unsetAllowedGrantTypes());
    Assertions.assertFalse(value.getAllowedGrantTypesValue().isPresent(),
        "Unset must clear the value");
  }
}
